if(url.pathname.startsWith('/api/catalog-images/')&&request.method==='GET'){const path=url.pathname.slice('/api/catalog-images/'.length);if(!APP_CATALOG.some(i=>i.imageUrl==='/api/catalog-images/'+path)&&!(typeof APP_ARCHIVE_RESOURCE_BASELINE!=='undefined'&&APP_ARCHIVE_RESOURCE_BASELINE.some(i=>i.imageUrl==='/api/catalog-images/'+path)))throw fail('Picture not found',404);if(typeof APP_SHEET_IMAGES!=='undefined'&&APP_SHEET_IMAGES[url.pathname])return new Response(Uint8Array.from(atob(APP_SHEET_IMAGES[url.pathname]),c=>c.charCodeAt(0)),{headers:{'Content-Type':'image/jpeg','Cache-Control':'private,max-age=86400'}});const key='catalog/'+path;let object=env.BUCKET?await env.BUCKET.get(key):null;if(object)return new Response(object.body,{headers:{'Content-Type':'image/jpeg','Cache-Control':'private,max-age=86400','X-Content-Type-Options':'nosniff'}});const legacyImage=typeof APP_ARCHIVE_RESOURCE_BASELINE!=='undefined'&&APP_ARCHIVE_RESOURCE_BASELINE.some(i=>i.imageUrl===url.pathname);const imageRevision=path.endsWith('-isv-gap-v1.jpg')?ISV_GAP_IMAGE_REVISION:path.endsWith('-owner-photo-v1.jpg')?OWNER_PHOTO_REVISION:path.endsWith('-mastersheet-v1.jpg')?MASTERSHEET_IMAGE_REVISION:path.endsWith('-batch5-v1.jpg')?BATCH_FIVE_IMAGE_REVISION:path.endsWith('-batch4-v1.jpg')?BATCH_FOUR_IMAGE_REVISION:legacyImage?'3f8715d4649c65763abe321b5d311a07cc774f7d':'18d984479d00ac6ae0ed88356d1bb4b4cd216544';const response=await fetch('https://raw.githubusercontent.com/steveh00898/SS/'+imageRevision+'/data/images/'+path);if(!response.ok)throw fail('Picture unavailable',502);const bytes=await response.arrayBuffer();if(env.BUCKET)await env.BUCKET.put(key,bytes,{httpMetadata:{contentType:'image/jpeg'}});return new Response(bytes,{headers:{'Content-Type':'image/jpeg','Cache-Control':'private,max-age=86400','X-Content-Type-Options':'nosniff'}})}
